-- Sandbox-only access boundary. Original module functions and policies stay unchanged.
DO $target$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.tenants WHERE tenant_code='QUALISPHERE-SANDBOX' AND status='inactive') OR (SELECT count(*) FROM public.tenants WHERE is_internal)<>1 THEN RAISE EXCEPTION 'Expected isolated internal clone'; END IF;
END $target$;
CREATE SCHEMA clone_runtime;
REVOKE ALL ON SCHEMA clone_runtime FROM PUBLIC,anon;
CREATE TABLE clone_runtime.testers(user_id uuid PRIMARY KEY REFERENCES auth.users(id) ON DELETE CASCADE);
ALTER TABLE clone_runtime.testers ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON clone_runtime.testers FROM PUBLIC,anon,authenticated;
INSERT INTO clone_runtime.testers SELECT u.id FROM auth.users u JOIN public.platform_administrators p ON lower(p.user_email)=lower(u.email) AND p.is_active;
CREATE FUNCTION clone_runtime.allowed_user() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $allowed$
 SELECT auth.uid() IS NOT NULL
 AND EXISTS(SELECT 1 FROM clone_runtime.testers t JOIN auth.users u ON u.id=t.user_id JOIN public.user_roles r ON lower(r.user_email)=lower(u.email) WHERE t.user_id=auth.uid() AND lower(coalesce(r.account_status,'active'))='active' AND lower(u.email)=lower(auth.jwt()->>'email'))
 AND EXISTS(SELECT 1 FROM auth.sessions s WHERE s.user_id=auth.uid() AND s.id::text=auth.jwt()->>'session_id');
$allowed$;
REVOKE ALL ON FUNCTION clone_runtime.allowed_user() FROM PUBLIC,anon;
GRANT USAGE ON SCHEMA clone_runtime TO authenticated,service_role;
GRANT EXECUTE ON FUNCTION clone_runtime.allowed_user() TO authenticated,service_role;
CREATE FUNCTION clone_runtime.check_request() RETURNS void LANGUAGE plpgsql SECURITY INVOKER SET search_path='' AS $check$
BEGIN
 IF auth.jwt()->>'role'='service_role' THEN RETURN; END IF;
 IF NOT coalesce(clone_runtime.allowed_user(),false) THEN RAISE insufficient_privilege USING MESSAGE='This internal sandbox is restricted to approved test accounts.'; END IF;
END $check$;
REVOKE ALL ON FUNCTION clone_runtime.check_request() FROM PUBLIC;
GRANT USAGE ON SCHEMA clone_runtime TO anon;
GRANT EXECUTE ON FUNCTION clone_runtime.check_request() TO anon,authenticated,service_role;
ALTER ROLE authenticator SET pgrst.db_pre_request='clone_runtime.check_request';
NOTIFY pgrst,'reload config';

